import { useState, FormEvent } from 'react';
import {
  JxInputField,
  JxSelect,
  JxSwitch,
  JxButton,
  JxAlert,
} from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function InviteTeamMemberForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [submitted, setSubmitted] = useState(false);

  const emailTouched = email.length > 0;
  const emailValid = EMAIL_PATTERN.test(email);
  const emailError = emailTouched && !emailValid ? 'Введите корректный адрес почты' : undefined;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!emailValid) return;
    setSubmitted(true);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)', maxWidth: 420 }}>
      {submitted && (
        <JxAlert
          intent="success"
          title="Приглашение отправлено"
          onClose={() => setSubmitted(false)}
        >
          {email} приглашён(а) в команду{notify ? ', уведомление отправлено' : ''}.
        </JxAlert>
      )}

      <form
        onSubmit={handleSubmit}
        style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}
      >
        <JxInputField
          label="Электронная почта"
          type="email"
          required
          placeholder="name@company.com"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          errorText={emailError}
          helperText={emailError ? undefined : 'Отправим приглашение на этот адрес'}
        />

        <JxSelect
          label="Роль"
          options={[
            { value: 'member', label: 'Участник' },
            { value: 'admin', label: 'Администратор' },
            { value: 'viewer', label: 'Наблюдатель' },
          ]}
          value={role}
          onValueChange={setRole}
        />

        <JxSwitch
          label="Отправить уведомление на почту"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <JxButton type="submit" variant="primary" disabled={!emailValid}>
          Отправить приглашение
        </JxButton>
      </form>
    </div>
  );
}

